INSERT INTO testimonials (ceo_name, ceo_title, company, headline, quote_short, quote_full, photo_url, display_order) VALUES
(
  'D. Brian Beardmore, MBA',
  'CEO and Founder',
  'PersonixHealth, Inc.',
  'Servant leadership is the operating system',
  'Eisavant sharpened the conviction my whole career had been teaching me: servant leadership is not a soft skill — it is the CEO''s operating system. Serve your people first, then seize the day. Carpe Diem!',
  'After more than three decades in healthcare technology — from building applications at Memorial Hermann Health System to serving as Chief Digital Officer at Presbyterian Healthcare Services, and now founding PersonixHealth — I stepped into the founder''s seat knowing the loneliest part of leadership is carrying the hard calls alone. Eisavant''s mentorship met me exactly at that transition. My mentor reinforced what my career had been teaching me all along: servant leadership is not a soft skill, it is the operating system of a durable company. When you serve your team first — clearing obstacles, governing responsibly, and putting patients and people ahead of ego — trust compounds and scale follows. That philosophy carried us from scaling telehealth to half of all ambulatory visits in ninety days to building PersonixHealth into an AI-native platform for enterprise health systems. To every executive weighing this program: the seat is only lonely if you choose to sit alone. Carpe Diem!',
  '/images/brian-beardmore.jpg',
  0
);
